// Worker entry: a thin wrapper around the OpenNext handler.
//
// Plain-HTTP requests to the canonical host are redirected to HTTPS before
// they reach the app. Everything else is passed through unchanged.

// @ts-ignore — generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

export function canonicalHttpsRedirect(request: Request, appUrl: string | undefined): Response | null {
  if (!appUrl) return null;
  let canonical: URL;
  try {
    canonical = new URL(appUrl);
  } catch {
    return null;
  }
  const url = new URL(request.url);
  if (canonical.protocol === 'https:' && url.protocol === 'http:' && url.hostname === canonical.hostname) {
    url.protocol = 'https:';
    url.port = '';
    return Response.redirect(url.toString(), 308);
  }
  return null;
}

export default {
  async fetch(request: Request, env: { APP_URL?: string }, ctx: unknown) {
    return canonicalHttpsRedirect(request, env.APP_URL) ?? handler.fetch(request, env, ctx);
  },
};

// Durable Objects OpenNext may reference (unused by this config, re-exported
// so the generated handler's bindings stay resolvable).
// @ts-ignore — generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
